import React, { useState, useEffect } from 'react';

// ============================================================================
// SECTION 1: USCIS CIVICS TEST - OFFICIAL & SUPPLEMENTARY QUESTIONS
// ============================================================================

const civicsOfficialQuestions = [
  // A: Principles of American Government
  { id: 1, question: "What is the form of government of the United States?", choices: ["Republic", "Constitutional monarchy", "Direct democracy", "Parliamentary system"], correct: 0, explanation: "アメリカ合衆国は共和制です。これは人民が統治権を保有し、選出された代表者を通じて権力を行使する政治体制です。", isOfficial: true, is6520: false, category: "A: Principles" },
  { id: 2, question: "What is the supreme law of the land?", choices: ["The Declaration of Independence", "The U.S. Constitution", "The Bill of Rights", "Federal laws"], correct: 1, explanation: "アメリカ合衆国憲法はアメリカの最高法典です。すべての州法や連邦法はこれに準拠する必要があります。", isOfficial: true, is6520: true, category: "A: Principles" },
  { id: 3, question: "Name one thing the U.S. Constitution does.", choices: ["Establishes political parties", "Forms the government", "Declares independence", "Regulates commerce only"], correct: 1, explanation: "憲法は政府の構造を形成し、その権限を定義し、国民の基本的人権を保護します。", isOfficial: true, is6520: false, category: "A: Principles" },
  { id: 4, question: "The U.S. Constitution starts with the words 'We the People.' What does this mean?", choices: ["The President leads the people", "People should govern themselves", "The military rules", "States are independent"], correct: 1, explanation: "『We the People』は人民主権の原則を表します。政府の権力は国民の同意に由来しており、国民が最終的な統治権を保持しています。", isOfficial: true, is6520: false, category: "A: Principles" },
  { id: 5, question: "How are changes made to the U.S. Constitution?", choices: ["By Congress alone", "By the President alone", "Through amendments", "By the Supreme Court only"], correct: 2, explanation: "憲法の変更は改正を通じて行われます。改正は議会の3分の2の承認と、3分の4の州の批准が必要です。", isOfficial: true, is6520: false, category: "A: Principles" },
  { id: 6, question: "What does the Bill of Rights protect?", choices: ["National borders", "Individual rights of people", "Government structures", "Military operations"], correct: 1, explanation: "権利章典はアメリカ国民の基本的人権を保護します。言論の自由、宗教の自由、平等な権利などが含まれます。", isOfficial: true, is6520: false, category: "A: Principles" },
  { id: 7, question: "How many amendments does the U.S. Constitution have?", choices: ["10", "20", "27", "35"], correct: 2, explanation: "アメリカ合衆国憲法には27の改正があります。最初の10は権利章典として知られています。", isOfficial: true, is6520: true, category: "A: Principles" },
  { id: 8, question: "Why is the Declaration of Independence important?", choices: ["It created the Constitution", "It says America is free from British control", "It established the federal government", "It created political parties"], correct: 1, explanation: "独立宣言は1776年に採択され、アメリカがイギリスからの独立を宣言した重要な文書です。すべての人は平等に創造されたという原則を表明しています。", isOfficial: true, is6520: false, category: "A: Principles" },
  { id: 9, question: "What founding document said the American colonies were free from Britain?", choices: ["The Constitution", "The Declaration of Independence", "The Magna Carta", "The Mayflower Compact"], correct: 1, explanation: "独立宣言は1776年7月4日にアメリカ13州がイギリスからの独立を宣言した文書です。", isOfficial: true, is6520: false, category: "A: Principles" },
  { id: 10, question: "Name two important ideas from the Declaration of Independence and the U.S. Constitution.", choices: ["Monarchy and nobility", "Equality and liberty", "Taxation only", "Military rule"], correct: 1, explanation: "平等と自由はアメリカの建国文書における最も重要な概念です。すべての人に固有の権利があるという考えが基礎となっています。", isOfficial: true, is6520: false, category: "A: Principles" },
  { id: 11, question: "The words 'Life, Liberty, and the pursuit of Happiness' are in what founding document?", choices: ["The Constitution", "The Bill of Rights", "The Declaration of Independence", "The Federalist Papers"], correct: 2, explanation: "この有名な言葉は1776年の独立宣言に含まれています。人間は固有の権利を持って創造されているという思想を表現しています。", isOfficial: true, is6520: false, category: "A: Principles" },
  { id: 12, question: "What is the economic system of the United States?", choices: ["Socialism", "Communism", "Capitalism", "Feudalism"], correct: 2, explanation: "資本主義は、個人と企業が商品とサービスを所有・生産・交換できる経済体制です。市場メカニズムが資源配分を決定します。", isOfficial: true, is6520: true, category: "A: Principles" },
  { id: 13, question: "What is the rule of law?", choices: ["The President makes all laws", "Everyone must follow the law", "Only rich people follow laws", "States can ignore federal laws"], correct: 1, explanation: "法の支配は、すべての人が法の下で平等であり、法を超える人や機関はないという原則です。", isOfficial: true, is6520: false, category: "A: Principles" },
  { id: 14, question: "Many documents influenced the U.S. Constitution. Name one.", choices: ["The Bible", "The Declaration of Independence", "English novels", "Religious texts only"], correct: 1, explanation: "独立宣言、連合規約、フェデラリスト論文、および他の歴史的文書が憲法に影響を与えました。", isOfficial: true, is6520: false, category: "A: Principles" },
  { id: 15, question: "There are three branches of government. Why?", choices: ["To make government more efficient", "So one part does not become too powerful", "To increase the President's power", "To eliminate state governments"], correct: 1, explanation: "権力の分離は、権力が一つの枝に集中しないようにするための憲法の基本原則です。抑制と均衡を通じて権力を分配します。", isOfficial: true, is6520: false, category: "A: Principles" },

  // B: System of Government
  { id: 16, question: "Name the three branches of government.", choices: ["Executive, legislative, legal", "Federal, state, local", "Legislative, executive, and judicial", "Primary, secondary, tertiary"], correct: 2, explanation: "3つの政府部門は立法部（議会）、行政部（大統領）、司法部（裁判所）です。各部門は異なる機能を持ちます。", isOfficial: true, is6520: false, category: "B: System" },
  { id: 17, question: "The President of the United States is in charge of which branch of government?", choices: ["Legislative", "Judicial", "Executive", "All three"], correct: 2, explanation: "大統領は行政部を統括しており、法律を執行し、軍を指揮し、外交を行う責任があります。", isOfficial: true, is6520: false, category: "B: System" },
  { id: 18, question: "What part of the federal government writes laws?", choices: ["The President", "The Supreme Court", "Congress", "The states"], correct: 2, explanation: "議会（上院と下院）が連邦法を制定します。この権力は憲法第1条に規定されています。", isOfficial: true, is6520: false, category: "B: System" },
  { id: 19, question: "What are the two parts of the U.S. Congress?", choices: ["House and Senate", "Upper and lower chambers", "Senate and House of Representatives", "Federal and state"], correct: 2, explanation: "議会は上院（各州2議員）と下院（435議員、人口比例）で構成されています。", isOfficial: true, is6520: false, category: "B: System" },
  { id: 20, question: "Name one power of the U.S. Congress.", choices: ["Appoints judges", "Enforces laws", "Writes laws", "Commands the military"], correct: 2, explanation: "議会の権限には、法律制定、予算承認、戦争宣言、およびその他の重要な権限が含まれます。", isOfficial: true, is6520: true, category: "B: System" },
  { id: 21, question: "How many U.S. senators are there?", choices: ["50", "100", "150", "200"], correct: 1, explanation: "アメリカには100人の上院議員がいます。各州から2人ずつです。", isOfficial: true, is6520: false, category: "B: System" },
  { id: 22, question: "How long is a term for a U.S. senator?", choices: ["2 years", "4 years", "6 years", "8 years"], correct: 2, explanation: "上院議員の任期は6年です。3分の1の議員が2年ごとに改選されます。", isOfficial: true, is6520: false, category: "B: System" },
  { id: 23, question: "Who is one of your state's U.S. senators now?", choices: ["Answers vary by state", "The President", "The governor", "The mayor"], correct: 0, explanation: "上院議員は州によって異なります。あなたの州の公式ウェブサイトで確認してください。", isOfficial: true, is6520: false, category: "B: System" },
  { id: 24, question: "How many voting members are in the House of Representatives?", choices: ["100", "300", "435", "500"], correct: 2, explanation: "下院には435人の投票権を有する議員がいます。各州の議員数は人口に基づいています。", isOfficial: true, is6520: false, category: "B: System" },
  { id: 25, question: "How long is a term for a member of the House of Representatives?", choices: ["2 years", "3 years", "4 years", "6 years"], correct: 0, explanation: "下院議員の任期は2年です。毎年すべての議員が改選対象になります。", isOfficial: true, is6520: false, category: "B: System" },
  { id: 26, question: "Why do U.S. representatives serve shorter terms than U.S. senators?", choices: ["They have less power", "To make government more democratic", "To more closely follow public opinion", "Because they earn less"], correct: 2, explanation: "下院議員の2年任期は、代表者をより直接的に世論に反応させることを目的としています。", isOfficial: true, is6520: false, category: "B: System" },
  { id: 27, question: "How many senators does each state have?", choices: ["One", "Two", "Three", "Four"], correct: 1, explanation: "各州は上院に2人の議員を送ります。これは小規模州に平等な代表を提供します。", isOfficial: true, is6520: false, category: "B: System" },
  { id: 28, question: "Why does each state have two senators?", choices: ["Historical accident", "Equal representation for all states", "Population determines it", "The President decided it"], correct: 1, explanation: "各州が2人の上院議員を有することは、州の規模に関係なく平等な代表を確保します。これは大妥協です。", isOfficial: true, is6520: false, category: "B: System" },
  { id: 29, question: "Name your U.S. representative.", choices: ["Answers vary", "The President", "Your senator", "The governor"], correct: 0, explanation: "下院議員はあなたの議会地区によって決まります。公式ウェブサイトで確認してください。", isOfficial: true, is6520: false, category: "B: System" },
  { id: 30, question: "What is the name of the Speaker of the House of Representatives now?", choices: ["Varies - see uscis.gov/citizenship/testupdates", "The President", "The Senate leader", "The Chief Justice"], correct: 0, explanation: "下院議長は下院の多数党によって選出される重要な役職です。USCIS のウェブサイトで現在の名前を確認してください。", isOfficial: true, is6520: true, category: "B: System" },
  { id: 31, question: "Who does a U.S. senator represent?", choices: ["Their political party", "Citizens of their state", "The federal government", "The President"], correct: 1, explanation: "上院議員はその州のすべての市民を代表しています。州の全人口を代表する責任があります。", isOfficial: true, is6520: false, category: "B: System" },
  { id: 32, question: "Who elects U.S. senators?", choices: ["State legislatures", "The President", "Citizens from their state", "Federal government"], correct: 2, explanation: "修正第17条（1913年）により、上院議員は州の市民による直接選挙で選出されます。", isOfficial: true, is6520: false, category: "B: System" },
  { id: 33, question: "Who does a member of the House of Representatives represent?", choices: ["Their state", "The federal government", "Citizens in their congressional district", "The President"], correct: 2, explanation: "下院議員は特定の議会地区の市民を代表しています。各地区から1人の議員が選出されます。", isOfficial: true, is6520: false, category: "B: System" },
  { id: 34, question: "Who elects members of the House of Representatives?", choices: ["State legislatures", "The Senate", "Citizens from their congressional district", "The President"], correct: 2, explanation: "下院議員は議会地区内の市民による直接選挙で選出されます。", isOfficial: true, is6520: false, category: "B: System" },
  { id: 35, question: "Some states have more representatives than other states. Why?", choices: ["Larger states are more important", "Because of the state's population", "It's based on land area", "It's decided by the President"], correct: 1, explanation: "下院の議員数は各州の人口に比例しています。人口が多い州ほど多くの議員を有しています。", isOfficial: true, is6520: false, category: "B: System" },
  { id: 36, question: "The President of the United States is elected for how many years?", choices: ["2 years", "3 years", "4 years", "6 years"], correct: 2, explanation: "大統領の任期は4年です。最大で2期（8年）務めることができます。", isOfficial: true, is6520: true, category: "B: System" },
  { id: 37, question: "The President of the United States can serve only two terms. Why?", choices: ["The people voted for it", "Because of the 22nd Amendment", "The Constitution originally said so", "Congress decided it"], correct: 1, explanation: "修正第22条（1951年）は大統領を2期（8年）に限定しています。1つの人物に過度な権力が集中するのを防ぐためです。", isOfficial: true, is6520: false, category: "B: System" },
  { id: 38, question: "What is the name of the President of the United States now?", choices: ["Varies - see uscis.gov/citizenship/testupdates", "It changes every 2 years", "The Supreme Court selects it", "Congress appoints it"], correct: 0, explanation: "現在の大統領の名前は、USCIS のウェブサイトで確認してください。テストの時間により異なります。", isOfficial: true, is6520: true, category: "B: System" },
  { id: 39, question: "What is the name of the Vice President of the United States now?", choices: ["Varies - see uscis.gov/citizenship/testupdates", "The President appoints them", "Congress elects them", "The Supreme Court decides"], correct: 0, explanation: "現在の副大統領の名前は、USCIS のウェブサイトで確認してください。", isOfficial: true, is6520: true, category: "B: System" },
  { id: 40, question: "If the president can no longer serve, who becomes president?", choices: ["Congress", "The Senate", "The Vice President", "The Chief Justice"], correct: 2, explanation: "大統領が職務を遂行できない場合、副大統領が大統領になります。憲法第25条で規定されています。", isOfficial: true, is6520: false, category: "B: System" },
  { id: 41, question: "Name one power of the president.", choices: ["Makes laws alone", "Appoints judges", "Commands Congress", "Controls state governments"], correct: 1, explanation: "大統領の権限には、法案への署名、裁判官の任命、軍の指揮、条約の締結が含まれます。", isOfficial: true, is6520: false, category: "B: System" },
  { id: 42, question: "Who is Commander in Chief of the U.S. military?", choices: ["Congress", "The Senate", "The President", "The generals"], correct: 2, explanation: "大統領は米国軍隊の総司令官です。軍隊の戦術的・戦略的な指揮権を持ちます。", isOfficial: true, is6520: false, category: "B: System" },
  { id: 43, question: "Who signs bills to become laws?", choices: ["Congress", "The Senate alone", "The President", "The Chief Justice"], correct: 2, explanation: "大統領が法案に署名すると、それは法律になります。大統領は拒否権を使って法案を拒否することもできます。", isOfficial: true, is6520: false, category: "B: System" },
  { id: 44, question: "Who vetoes bills?", choices: ["Congress", "The Senate", "The President", "The courts"], correct: 2, explanation: "大統領は議会で可決された法案に対して拒否権を行使できます。議会は2/3の投票で拒否権を覆すことができます。", isOfficial: true, is6520: true, category: "B: System" },
  { id: 45, question: "Who appoints federal judges?", choices: ["Congress", "The Senate alone", "The President", "The voters"], correct: 2, explanation: "大統領は連邦判事を任命します。任命は上院の承認が必要です。", isOfficial: true, is6520: false, category: "B: System" },
  { id: 46, question: "The executive branch has many parts. Name one.", choices: ["The courts", "Congress", "The Cabinet", "State governments"], correct: 2, explanation: "行政部は大統領、副大統領、内閣、および連邦機関で構成されています。", isOfficial: true, is6520: false, category: "B: System" },
  { id: 47, question: "What does the President's Cabinet do?", choices: ["Makes laws", "Appoints Congress members", "Advises the President", "Votes in Senate"], correct: 2, explanation: "内閣は大統領の主要な顧問グループです。各内閣メンバーは重要な政府機関を統括しています。", isOfficial: true, is6520: false, category: "B: System" },
  { id: 48, question: "What are two Cabinet-level positions?", choices: ["Senator and Representative", "Attorney General and Secretary of State", "Judge and lawyer", "Mayor and governor"], correct: 1, explanation: "内閣レベルのポジションには、司法長官、国務長官、国防長官、および他の主要な役職が含まれます。", isOfficial: true, is6520: false, category: "B: System" },
  { id: 49, question: "Why is the Electoral College important?", choices: ["It makes voting easier", "It decides who is elected president", "It controls Congress", "It appoints judges"], correct: 1, explanation: "選挙人団は大統領選挙に勝つために必要なシステムです。各州の選挙人数はその州の議会議員の総数です。", isOfficial: true, is6520: false, category: "B: System" },
  { id: 50, question: "What is one part of the judicial branch?", choices: ["The President", "Congress", "Supreme Court", "The Cabinet"], correct: 2, explanation: "司法部は最高裁判所と連邦裁判所で構成されています。法律を解釈し、その憲法性を判断します。", isOfficial: true, is6520: false, category: "B: System" },
  { id: 51, question: "What does the judicial branch do?", choices: ["Makes laws", "Enforces laws", "Reviews laws", "Starts wars"], correct: 2, explanation: "司法部は法律を解釈し、その合憲性を判断し、法的紛争を解決します。", isOfficial: true, is6520: false, category: "B: System" },
  { id: 52, question: "What is the highest court in the United States?", choices: ["Federal courts", "State courts", "Supreme Court", "District courts"], correct: 2, explanation: "最高裁判所は米国司法制度の最高機関です。憲法上の問題に関する最終的な決定権を持ちます。", isOfficial: true, is6520: true, category: "B: System" },
  { id: 53, question: "How many seats are on the Supreme Court?", choices: ["5", "7", "9", "11"], correct: 2, explanation: "最高裁判所には9つの座があります。1人の主任司法官と8人の準司法官です。", isOfficial: true, is6520: false, category: "B: System" },
  { id: 54, question: "How many Supreme Court justices are usually needed to decide a case?", choices: ["3", "5", "7", "All 9"], correct: 1, explanation: "ほとんどの判例では、最高裁の判決には5人以上の司法官の同意が必要です。", isOfficial: true, is6520: false, category: "B: System" },
  { id: 55, question: "How long do Supreme Court justices serve?", choices: ["10 years", "15 years", "For life", "20 years"], correct: 2, explanation: "最高裁判官は終身制です。退職するか、弾劾されるまで職に就きます。", isOfficial: true, is6520: false, category: "B: System" },
  { id: 56, question: "Supreme Court justices serve for life. Why?", choices: ["To save money", "To be independent of politics", "Because they are very smart", "To prevent elections"], correct: 1, explanation: "終身制により、司法官は政治的圧力から保護され、独立した判断を下すことができます。", isOfficial: true, is6520: false, category: "B: System" },
  { id: 57, question: "Who is the Chief Justice of the United States now?", choices: ["Varies - see uscis.gov/citizenship/testupdates", "The President", "The Senate leader", "The Speaker of the House"], correct: 0, explanation: "現在の最高裁判所長官の名前は、USCIS のウェブサイトで確認してください。", isOfficial: true, is6520: false, category: "B: System" },
  { id: 58, question: "Name one power that is only for the federal government.", choices: ["Provide education", "Establish police", "Print money", "Issue licenses"], correct: 2, explanation: "連邦政府のみの権力には、紙幣印刷、条約締結、戦争宣言が含まれます。", isOfficial: true, is6520: false, category: "B: System" },
  { id: 59, question: "Name one power that is only for the states.", choices: ["Declare war", "Print money", "Provide education", "Make treaties"], correct: 2, explanation: "州のみの権力には、教育提供、警察保護、免許発行、土地利用許可が含まれます。", isOfficial: true, is6520: false, category: "B: System" },
  { id: 60, question: "What is the purpose of the 10th Amendment?", choices: ["It protects free speech", "It ends slavery", "Powers not given to federal government belong to states or people", "It establishes the courts"], correct: 2, explanation: "修正第10条は、憲法で連邦政府に与えられていない権力は州または国民に帰属することを規定しています。", isOfficial: true, is6520: false, category: "B: System" },
  { id: 61, question: "Who is the governor of your state now?", choices: ["Varies by state", "The President", "A federal judge", "The Mayor"], correct: 0, explanation: "州知事は州によって異なります。あなたの州の公式ウェブサイトで確認してください。", isOfficial: true, is6520: true, category: "B: System" },
  { id: 62, question: "What is the capital of your state?", choices: ["Varies by state", "Always Washington D.C.", "The largest city", "The oldest city"], correct: 0, explanation: "州の首都は州によって異なります。あなたの州の公式情報で確認してください。", isOfficial: true, is6520: true, category: "B: System" },

  // C: Rights and Responsibilities
  { id: 63, question: "There are four amendments to the U.S. Constitution about who can vote. Describe one of them.", choices: ["Women can't vote", "Citizens 18 and older can vote", "Only men can vote", "Only landowners can vote"], correct: 1, explanation: "修正第26条は、18歳以上のすべての市民に投票権を与えます。また、修正第15条、19条、26条も投票権に関連しています。", isOfficial: true, is6520: false, category: "C: Rights" },
  { id: 64, question: "Who can vote in federal elections, run for federal office, and serve on a jury in the United States?", choices: ["Permanent residents", "Non-citizens", "U.S. citizens", "Teenagers"], correct: 2, explanation: "米国市民のみが連邦選挙で投票し、連邦職に就任し、陪審員として奉仕することができます。", isOfficial: true, is6520: false, category: "C: Rights" },
  { id: 65, question: "What are three rights of everyone living in the United States?", choices: ["Freedom of expression", "Freedom of religion", "Right to own guns", "All of the above"], correct: 3, explanation: "米国に住むすべての人の基本的権利には、言論の自由、宗教の自由、集会の自由、請願の自由が含まれます。", isOfficial: true, is6520: false, category: "C: Rights" },
  { id: 66, question: "What do we show loyalty to when we say the Pledge of Allegiance?", choices: ["The President", "Congress", "The United States", "The military"], correct: 2, explanation: "忠誠の誓いはアメリカ合衆国とその国旗に対する忠誠を示しています。", isOfficial: true, is6520: true, category: "C: Rights" },
  { id: 67, question: "Name two promises that new citizens make in the Oath of Allegiance.", choices: ["Give up loyalty to other countries", "Defend the Constitution", "Obey U.S. laws", "All of the above"], correct: 3, explanation: "帰化誓約では、新市民は他国への忠誠を放棄し、憲法を守り、米国法を守ることを誓います。", isOfficial: true, is6520: false, category: "C: Rights" },
  { id: 68, question: "How can people become United States citizens?", choices: ["By being born here", "By naturalization", "By working for the government", "All of the above"], correct: 3, explanation: "米国市民になるには、米国で出生するか、帰化手続きを通じて市民になる必要があります。", isOfficial: true, is6520: false, category: "C: Rights" },
  { id: 69, question: "What are two examples of civic participation in the United States?", choices: ["Voting", "Joining a political party", "Running for office", "All of the above"], correct: 3, explanation: "市民参加には、投票、政治活動、コミュニティ組織への参加、公職への立候補が含まれます。", isOfficial: true, is6520: false, category: "C: Rights" },
  { id: 70, question: "What is one way Americans can serve their country?", choices: ["Vote", "Serve in the military", "Pay taxes", "All of the above"], correct: 3, explanation: "米国民は投票、兵役、納税、または公職を通じて国に奉仕できます。", isOfficial: true, is6520: false, category: "C: Rights" },
  { id: 71, question: "Why is it important to pay federal taxes?", choices: ["It's required by law", "It funds the government", "It's a civic duty", "All of the above"], correct: 3, explanation: "連邦税は政府機能の資金調達に必要であり、すべての市民の責任です。", isOfficial: true, is6520: false, category: "C: Rights" },
  { id: 72, question: "It is important for all men age 18 through 25 to register for the Selective Service. Name one reason why.", choices: ["It's required by law", "It's a civic duty", "For potential draft purposes", "All of the above"], correct: 3, explanation: "選抜徴兵制登録は法律により必須であり、市民的責任です。緊急時のドラフトの公正性を維持するためです。", isOfficial: true, is6520: false, category: "C: Rights" },

  // D: Colonial Period and Independence
  { id: 73, question: "The colonists came to America for many reasons. Name one.", choices: ["Adventure only", "Religious freedom", "Economic opportunity", "Both religious and economic reasons"], correct: 3, explanation: "植民者はアメリカに迫害からの解放、宗教の自由、経済的機会を求めて来ました。", isOfficial: true, is6520: false, category: "D: Colonial" },
  { id: 74, question: "Who lived in America before the Europeans arrived?", choices: ["Asian immigrants", "American Indians", "African people", "No one"], correct: 1, explanation: "アメリカ・インディアンは、ヨーロッパ人の到着前にアメリカに住んでいた先住民です。", isOfficial: true, is6520: true, category: "D: Colonial" },
  { id: 75, question: "What group of people was taken and sold as slaves?", choices: ["European criminals", "Africans", "Asian workers", "American Indians primarily"], correct: 1, explanation: "アフリカ人は強制的に捕虜にされ、アメリカで奴隷として売られました。この実践は数百年続きました。", isOfficial: true, is6520: false, category: "D: Colonial" },
  { id: 76, question: "What war did the Americans fight to win independence from Britain?", choices: ["French and Indian War", "American Revolutionary War", "War of 1812", "Civil War"], correct: 1, explanation: "アメリカ独立戦争（1775-1783年）は、アメリカがイギリスから独立するために戦った戦争です。", isOfficial: true, is6520: false, category: "D: Colonial" },
  { id: 77, question: "Name one reason why the Americans declared independence from Britain.", choices: ["High taxes", "Lack of representation", "Military occupation", "All of the above"], correct: 3, explanation: "アメリカ人はイギリスの高い税金、議会での代表権がないこと、そして抑圧的な政治に対して独立を宣言しました。", isOfficial: true, is6520: false, category: "D: Colonial" },
  { id: 78, question: "Who wrote the Declaration of Independence?", choices: ["George Washington", "Thomas Jefferson", "Benjamin Franklin", "John Adams"], correct: 1, explanation: "トマス・ジェファーソンは1776年の独立宣言の主要な著者でした。", isOfficial: true, is6520: true, category: "D: Colonial" },
  { id: 79, question: "When was the Declaration of Independence adopted?", choices: ["July 4, 1775", "July 4, 1776", "July 4, 1777", "July 4, 1778"], correct: 1, explanation: "独立宣言は1776年7月4日に採択されました。この日はアメリカの独立記念日として祝われています。", isOfficial: true, is6520: false, category: "D: Colonial" },
  { id: 80, question: "The American Revolution had many important events. Name one.", choices: ["Boston Tea Party", "Battle of Bunker Hill", "Valley Forge", "All of the above"], correct: 3, explanation: "独立戦争の重要な出来事には、ボストン茶会事件、バンカーヒルの戦い、バレーフォージでの冬営があります。", isOfficial: true, is6520: false, category: "D: Colonial" },
  { id: 81, question: "There were 13 original states. Name five.", choices: ["Virginia, Massachusetts, Pennsylvania, North Carolina, New York", "California, Texas, Florida, Ohio, Michigan", "All states founded in 1800s", "Southern states only"], correct: 0, explanation: "13の植民地州はニューハンプシャー、マサチューセッツ、ロードアイランド、コネチカット、ニューヨーク、ニュージャージー、ペンシルベニア、デラウェア、メリーランド、バージニア、ノースカロライナ、サウスカロライナ、ジョージアです。", isOfficial: true, is6520: false, category: "D: Colonial" },
  { id: 82, question: "What founding document was written in 1787?", choices: ["Declaration of Independence", "U.S. Constitution", "Bill of Rights", "Articles of Confederation"], correct: 1, explanation: "米国憲法は1787年に憲法制定会議で執筆されました。", isOfficial: true, is6520: false, category: "D: Colonial" },
  { id: 83, question: "The Federalist Papers supported the passage of the U.S. Constitution. Name one of the writers.", choices: ["Thomas Jefferson", "James Madison", "George Washington", "Benjamin Franklin"], correct: 1, explanation: "フェデラリスト論文はジェームス・マディソン、アレクサンダー・ハミルトン、およびジョン・ジェイによって書かれました。", isOfficial: true, is6520: false, category: "D: Colonial" },
  { id: 84, question: "Why were the Federalist Papers important?", choices: ["They opposed the Constitution", "They supported the Constitution", "They were entertainment", "They changed nothing"], correct: 1, explanation: "フェデラリスト論文は憲法の承認を支援し、そのメカニズムを説明しました。", isOfficial: true, is6520: false, category: "D: Colonial" },
  { id: 85, question: "Benjamin Franklin is famous for many things. Name one.", choices: ["Founded the first free public libraries", "First Postmaster General", "Helped write the Declaration of Independence", "All of the above"], correct: 3, explanation: "ベンジャミン・フランクリンは多くの偉業で有名です。彼は図書館を設立し、郵政局長となり、独立宣言を手伝いました。", isOfficial: true, is6520: false, category: "D: Colonial" },
  { id: 86, question: "George Washington is famous for many things. Name one.", choices: ["First President", "Father of Our Country", "General of the Continental Army", "All of the above"], correct: 3, explanation: "ジョージ・ワシントンは独立戦争の総司令官であり、最初の大統領です。彼は建国の父の一人です。", isOfficial: true, is6520: true, category: "D: Colonial" },
  { id: 87, question: "Thomas Jefferson is famous for many things. Name one.", choices: ["Wrote the Declaration of Independence", "Third President", "Louisiana Purchase", "All of the above"], correct: 3, explanation: "トマス・ジェファーソンは独立宣言の著者であり、第3代大統領であり、ルイジアナ領土を購入しました。", isOfficial: true, is6520: false, category: "D: Colonial" },
  { id: 88, question: "James Madison is famous for many things. Name one.", choices: ["Father of the Constitution", "Fourth President", "War of 1812 President", "All of the above"], correct: 3, explanation: "ジェームス・マディソンは憲法の父であり、第4代大統領です。彼は1812年戦争中に大統領でした。", isOfficial: true, is6520: false, category: "D: Colonial" },
  { id: 89, question: "Alexander Hamilton is famous for many things. Name one.", choices: ["First Secretary of Treasury", "Federalist Papers writer", "Aide to George Washington", "All of the above"], correct: 3, explanation: "アレクサンダー・ハミルトンは最初の財務長官であり、フェデラリスト論文を書き、ワシントンのスタッフでした。", isOfficial: true, is6520: false, category: "D: Colonial" },

  // E: 1800s
  { id: 90, question: "What territory did the United States buy from France in 1803?", choices: ["Alaska", "Louisiana Territory", "Florida", "Texas"], correct: 1, explanation: "米国はナポレオンからルイジアナ領土を購入しました。これにより米国の領土が2倍になりました。", isOfficial: true, is6520: false, category: "E: 1800s" },
  { id: 91, question: "Name one war fought by the United States in the 1800s.", choices: ["War of 1812", "Mexican-American War", "Civil War", "All of the above"], correct: 3, explanation: "19世紀に米国が戦った主な戦争には、1812年戦争、米墨戦争、南北戦争があります。", isOfficial: true, is6520: false, category: "E: 1800s" },
  { id: 92, question: "Name the U.S. war between the North and the South.", choices: ["French and Indian War", "Civil War", "War of 1812", "Mexican-American War"], correct: 1, explanation: "南北戦争（1861-1865年）は北部と南部の州の間で戦われました。", isOfficial: true, is6520: false, category: "E: 1800s" },
  { id: 93, question: "The Civil War had many important events. Name one.", choices: ["Battle of Gettysburg", "Emancipation Proclamation", "Battle of Fort Sumter", "All of the above"], correct: 3, explanation: "南北戦争の重要な出来事には、フォートサムター戦、ゲティスバーグ戦、エマンシペーション・プロクラメーションが含まれます。", isOfficial: true, is6520: false, category: "E: 1800s" },
  { id: 94, question: "Abraham Lincoln is famous for many things. Name one.", choices: ["Freed the slaves", "Saved the Union", "16th President", "All of the above"], correct: 3, explanation: "エイブラハム・リンカーン大統領は奴隷を解放し、連邦を維持し、第16代大統領です。", isOfficial: true, is6520: true, category: "E: 1800s" },
  { id: 95, question: "What did the Emancipation Proclamation do?", choices: ["Freed all people", "Freed slaves in the Confederacy", "Gave rights to all", "Changed the Constitution"], correct: 1, explanation: "エマンシペーション・プロクラメーションは南北戦争中に奴隷州の奴隷を解放しました。", isOfficial: true, is6520: false, category: "E: 1800s" },
  { id: 96, question: "What U.S. war ended slavery?", choices: ["War of 1812", "Mexican-American War", "Civil War", "Spanish-American War"], correct: 2, explanation: "南北戦争は奴隷制度を終わらせました。修正第13条は奴隷制を廃止しました。", isOfficial: true, is6520: false, category: "E: 1800s" },
  { id: 97, question: "What amendment says all persons born or naturalized in the United States are U.S. citizens?", choices: ["13th Amendment", "14th Amendment", "15th Amendment", "19th Amendment"], correct: 1, explanation: "修正第14条は、米国で生まれたまたは帰化したすべての人物に市民権を付与しています。", isOfficial: true, is6520: false, category: "E: 1800s" },
  { id: 98, question: "When did all men get the right to vote?", choices: ["Before the Civil War", "During the Civil War", "After the Civil War with the 15th Amendment", "In the 1900s"], correct: 2, explanation: "修正第15条（1870年）は、人種に関係なくすべての男性に投票権を与えました。", isOfficial: true, is6520: false, category: "E: 1800s" },
  { id: 99, question: "Name one leader of the women's rights movement in the 1800s.", choices: ["Susan B. Anthony", "Elizabeth Cady Stanton", "Sojourner Truth", "All of the above"], correct: 3, explanation: "19世紀の女性の権利運動の主要な指導者には、スーザン・B・アンソニー、エリザベス・ケイディ・スタントン、ソジャナー・トゥルースがいます。", isOfficial: true, is6520: false, category: "E: 1800s" },

  // F: Recent American History
  { id: 100, question: "Name one war fought by the United States in the 1900s.", choices: ["World War I", "World War II", "Korean War", "All of the above"], correct: 3, explanation: "20世紀に米国が戦った主な戦争には、第一次世界大戦、第二次世界大戦、朝鮮戦争があります。", isOfficial: true, is6520: false, category: "F: Recent History" },
  { id: 101, question: "Why did the United States enter World War I?", choices: ["Economic interests", "German ships attacked U.S.", "To support the Allies", "All of the above"], correct: 3, explanation: "米国は連合国の支援、ドイツ潜水艦による米国船舶への攻撃、および政治的利益のため第一次世界大戦に参加しました。", isOfficial: true, is6520: false, category: "F: Recent History" },
  { id: 102, question: "When did all women get the right to vote?", choices: ["1900", "1920", "1945", "1965"], correct: 1, explanation: "修正第19条（1920年）は、すべての女性に投票権を与えました。", isOfficial: true, is6520: false, category: "F: Recent History" },
  { id: 103, question: "What was the Great Depression?", choices: ["A war", "The longest economic recession", "A political party", "A natural disaster"], correct: 1, explanation: "大恐慌（1929年-1939年）は現代で最長の経済不況でした。失業と貧困が広がりました。", isOfficial: true, is6520: false, category: "F: Recent History" },
  { id: 104, question: "When did the Great Depression start?", choices: ["1920", "1929", "1933", "1939"], correct: 1, explanation: "大恐慌は1929年の株式市場の崩壊（黒い火曜日）で始まりました。", isOfficial: true, is6520: false, category: "F: Recent History" },
  { id: 105, question: "Who was president during the Great Depression and World War II?", choices: ["Herbert Hoover", "Franklin Roosevelt", "Harry Truman", "Dwight Eisenhower"], correct: 1, explanation: "フランクリン・ルーズベルト大統領は1933年から1945年まで、大恐慌と第二次世界大戦の期間に大統領でした。", isOfficial: true, is6520: false, category: "F: Recent History" },
  { id: 106, question: "Why did the United States enter World War II?", choices: ["To help Britain", "Pearl Harbor attack", "To stop Japan and Germany", "All of the above"], correct: 3, explanation: "米国は日本によるパールハーバー攻撃、および軸国（日本、ドイツ、イタリア）を停止するために第二次世界大戦に参加しました。", isOfficial: true, is6520: false, category: "F: Recent History" },
  { id: 107, question: "Dwight Eisenhower is famous for many things. Name one.", choices: ["General in WWII", "34th President", "Built the interstate highway system", "All of the above"], correct: 3, explanation: "ドワイト・アイゼンハワー将軍は第二次世界大戦中の司令官であり、第34代大統領です。彼は州間高速道路網を構築しました。", isOfficial: true, is6520: false, category: "F: Recent History" },
  { id: 108, question: "Who was the United States' main rival during the Cold War?", choices: ["Japan", "Germany", "Soviet Union", "China"], correct: 2, explanation: "ソビエト連邦は冷戦期間（1945年-1991年）における米国の主な対立者でした。", isOfficial: true, is6520: false, category: "F: Recent History" },
  { id: 109, question: "During the Cold War, what was one main concern of the United States?", choices: ["Communism", "Nuclear war", "Soviet expansion", "All of the above"], correct: 3, explanation: "冷戦中の米国の主な懸念は、共産主義の拡大、核戦争の可能性、およびソビエト膨張主義でした。", isOfficial: true, is6520: false, category: "F: Recent History" },
  { id: 110, question: "Why did the United States enter the Korean War?", choices: ["Economic interests", "To stop communism", "To help South Korea", "All of the above"], correct: 3, explanation: "米国は朝鮮戦争（1950-1953年）に共産主義の拡大を停止するため参加しました。", isOfficial: true, is6520: false, category: "F: Recent History" },
  { id: 111, question: "Why did the United States enter the Vietnam War?", choices: ["Economic interests", "To stop communism", "Cold War strategy", "All of the above"], correct: 3, explanation: "米国はベトナム戦争（1955-1975年）に冷戦戦略の一環として、共産主義拡大を停止するため参加しました。", isOfficial: true, is6520: false, category: "F: Recent History" },
  { id: 112, question: "What did the civil rights movement do?", choices: ["Started a war", "Fought to end racial discrimination", "Created new states", "Changed the economy"], correct: 1, explanation: "公民権運動（1950年代-1960年代）は人種差別を終わらせるために戦いました。", isOfficial: true, is6520: false, category: "F: Recent History" },
  { id: 113, question: "Martin Luther King, Jr. is famous for many things. Name one.", choices: ["Fought for civil rights", "Gave the 'I Have a Dream' speech", "Nobel Peace Prize winner", "All of the above"], correct: 3, explanation: "マーティン・ルーサー・キング・ジュニアは公民権運動の指導者であり、有名な『I Have a Dream』演説を行い、ノーベル平和賞を受賞しました。", isOfficial: true, is6520: true, category: "F: Recent History" },
  { id: 114, question: "Why did the United States enter the Persian Gulf War?", choices: ["Economic interests", "To force Iraq from Kuwait", "To stop terrorism", "All of the above"], correct: 3, explanation: "米国はペルシア湾戦争（1990-1991年）にイラクをクウェートから追放するため参加しました。", isOfficial: true, is6520: false, category: "F: Recent History" },
  { id: 115, question: "What major event happened on September 11, 2001 in the United States?", choices: ["Pearl Harbor attack", "Terrorists attacked the U.S.", "Tornado", "Earthquake"], correct: 1, explanation: "2001年9月11日、テロリストがアメリカを攻撃し、ニューヨークとワシントン D.C. の建物が標的となりました。", isOfficial: true, is6520: true, category: "F: Recent History" },
  { id: 116, question: "Name one U.S. military conflict after the September 11, 2001 attacks.", choices: ["War in Afghanistan", "War in Iraq", "War on Terror", "All of the above"], correct: 3, explanation: "2001年9月11日の攻撃後、米国はアフガニスタンとイラクで戦争を行いました。", isOfficial: true, is6520: false, category: "F: Recent History" },

  // G: Symbols and Holidays - Symbols
  { id: 117, question: "Name one American Indian tribe in the United States.", choices: ["Cherokee", "Navajo", "Apache", "All of the above"], correct: 3, explanation: "米国内には多くのアメリカ・インディアン民族があります。チェロキー族、ナバホ族、アパッチ族は主要な部族です。", isOfficial: true, is6520: false, category: "G: Symbols" },
  { id: 118, question: "Name one example of an American innovation.", choices: ["Light bulb", "Airplane", "Assembly line", "All of the above"], correct: 3, explanation: "アメリカンイノベーションには、電球、自動車、飛行機、組立ラインが含まれます。", isOfficial: true, is6520: false, category: "G: Symbols" },
  { id: 119, question: "What is the capital of the United States?", choices: ["New York", "Washington, D.C.", "Boston", "Philadelphia"], correct: 1, explanation: "ワシントン D.C. は米国の首都です。1791年に建設されました。", isOfficial: true, is6520: false, category: "G: Symbols" },
  { id: 120, question: "Where is the Statue of Liberty?", choices: ["Washington, D.C.", "New York Harbor", "Boston Harbor", "San Francisco"], correct: 1, explanation: "自由の女神はニューヨーク港のリバティ島にあります。移民のシンボルです。", isOfficial: true, is6520: false, category: "G: Symbols" },
  { id: 121, question: "Why does the flag have 13 stripes?", choices: ["Random design", "13 original colonies", "13 founding fathers", "13 states today"], correct: 1, explanation: "米国旗の13本の縞は、13の元の植民地を表しています。", isOfficial: true, is6520: true, category: "G: Symbols" },
  { id: 122, question: "Why does the flag have 50 stars?", choices: ["Population", "One star for each state", "Original states", "Symbols of freedom"], correct: 1, explanation: "米国旗の50つ星は、米国の50の州を表しています。", isOfficial: true, is6520: false, category: "G: Symbols" },
  { id: 123, question: "What is the name of the national anthem?", choices: ["America the Beautiful", "The Star-Spangled Banner", "God Bless America", "The Battle Hymn"], correct: 1, explanation: "『星条旗』は米国国歌です。1814年に作曲されました。", isOfficial: true, is6520: false, category: "G: Symbols" },
  { id: 124, question: "The Nation's first motto was 'E Pluribus Unum.' What does that mean?", choices: ["One nation forever", "Out of many, one", "United we stand", "For the people"], correct: 1, explanation: "『E Pluribus Unum』はラテン語で『多くの中から一つ』という意味です。米国の統一を表しています。", isOfficial: true, is6520: false, category: "G: Symbols" },

  // G: Symbols and Holidays - Holidays
  { id: 125, question: "What is Independence Day?", choices: ["Holiday for independence leaders", "A holiday to celebrate freedom from Britain", "A work day", "A military holiday"], correct: 1, explanation: "独立記念日は7月4日で、1776年のアメリカ独立宣言を祝います。", isOfficial: true, is6520: false, category: "G: Holidays" },
  { id: 126, question: "Name three national U.S. holidays.", choices: ["New Year's Day, Independence Day, Christmas", "Martin Luther King Jr. Day, Veterans Day, Thanksgiving", "Presidents Day, Memorial Day, Labor Day", "All of the above"], correct: 3, explanation: "米国の主要な全国的祝日には、元日、マーティン・ルーサー・キング・ジュニア・デー、大統領の日、メモリアルデー、独立記念日、労働者の日、退役軍人の日、感謝祭、クリスマス・デーが含まれます。", isOfficial: true, is6520: true, category: "G: Holidays" },
  { id: 127, question: "What is Memorial Day?", choices: ["Holiday for all workers", "A holiday to honor soldiers who died", "A summer celebration", "A political holiday"], correct: 1, explanation: "メモリアルデー（5月最終月曜日）は、軍事的奉仕で亡くなった兵士を追悼します。", isOfficial: true, is6520: false, category: "G: Holidays" },
  { id: 128, question: "What is Veterans Day?", choices: ["A military training day", "Holiday for retired soldiers", "A holiday to honor military service", "A work day"], correct: 2, explanation: "退役軍人の日（11月11日）は、米軍で奉仕したすべての人を称えます。", isOfficial: true, is6520: false, category: "G: Holidays" },
];

// Generate supplementary questions for Section 1
const civicsSupplementaryQuestions = [
  // Additional government questions
  { id: 201, question: "Which amendment abolished slavery?", choices: ["10th", "13th", "14th", "15th"], correct: 1, explanation: "修正第13条（1865年）は米国全体で奴隷制度を廃止しました。", isOfficial: false, is6520: false, category: "B: System" },
  { id: 202, question: "How many states are there in the United States?", choices: ["48", "50", "52", "45"], correct: 1, explanation: "米国には50の州があります。最後の2つはアラスカとハワイです。", isOfficial: false, is6520: false, category: "B: System" },
  { id: 203, question: "What is a veto?", choices: ["A law", "Congressional decision", "President's rejection of a bill", "A court ruling"], correct: 2, explanation: "拒否権（veto）は、大統領が議会で可決された法案を拒否する権力です。", isOfficial: false, is6520: false, category: "B: System" },
  { id: 204, question: "How can Congress override a presidential veto?", choices: ["Simple majority", "Two-thirds majority", "Three-fourths vote", "Unanimous vote"], correct: 1, explanation: "議会は、両院で2/3の投票で大統領の拒否権を覆すことができます。", isOfficial: false, is6520: false, category: "B: System" },
  { id: 205, question: "What is impeachment?", choices: ["Removal from office", "A formal charge", "A type of trial", "An arrest"], correct: 1, explanation: "弾劾は、公職者を職から除外するための正式な告発プロセスです。", isOfficial: false, is6520: false, category: "B: System" },
  { id: 206, question: "Who can be impeached?", choices: ["Only the President", "President and judges", "Any federal official", "All of the above"], correct: 3, explanation: "大統領、副大統領、判事、および他の連邦職員は弾劾されることがあります。", isOfficial: false, is6520: false, category: "B: System" },
  { id: 207, question: "Which house brings impeachment charges?", choices: ["Senate", "House of Representatives", "Supreme Court", "President"], correct: 1, explanation: "下院が弾劾を提起します。上院が裁判を行います。", isOfficial: false, is6520: false, category: "B: System" },
  { id: 208, question: "How many votes are needed to convict in an impeachment trial?", choices: ["Simple majority", "Two-thirds", "Three-fourths", "Unanimous"], correct: 1, explanation: "弾劾裁判で有罪判決を下すには、上院の2/3の投票が必要です。", isOfficial: false, is6520: false, category: "B: System" },
  { id: 209, question: "What is the cabinet?", choices: ["An office room", "President's advisors", "A type of government", "Congress members"], correct: 1, explanation: "内閣は、大統領の主要顧問グループで、各省庁の長が含まれます。", isOfficial: false, is6520: false, category: "B: System" },
  { id: 210, question: "How many justices make up the Supreme Court?", choices: ["5", "7", "9", "11"], correct: 2, explanation: "最高裁判所には9人の司法官があります。1人の主任と8人の準司法官です。", isOfficial: false, is6520: false, category: "B: System" },
  { id: 211, question: "What is the Senate's role in approving judges?", choices: ["They elect judges", "They confirm judges", "They vote on cases", "They have no role"], correct: 1, explanation: "上院は、大統領が任命した連邦判事を確認する権限があります。", isOfficial: false, is6520: false, category: "B: System" },
  { id: 212, question: "What is the purpose of checks and balances?", choices: ["Keep government efficient", "Prevent power concentration", "Reduce government size", "Increase taxes"], correct: 1, explanation: "抑制と均衡は、政府の各部門が他の部門を制限し、権力を防ぐシステムです。", isOfficial: false, is6520: false, category: "A: Principles" },
  { id: 213, question: "Which amendment gives Congress the power to tax income?", choices: ["10th", "15th", "16th", "17th"], correct: 2, explanation: "修正第16条（1913年）は、議会に所得税を徴収する権力を与えました。", isOfficial: false, is6520: false, category: "A: Principles" },
  { id: 214, question: "What is the Magna Carta?", choices: ["American document", "English document from 1215", "French law", "A treaty"], correct: 1, explanation: "マグナ・カルタは1215年のイギリスの文書で、君主の権力を制限しました。米国憲法に影響を与えました。", isOfficial: false, is6520: false, category: "A: Principles" },
  { id: 215, question: "What is the difference between the House and Senate?", choices: ["Only the House passes laws", "Senate only confirms judges", "House represents districts, Senate represents states", "No real difference"], correct: 2, explanation: "下院は議会地区を代表し、上院は各州を代表します。", isOfficial: false, is6520: false, category: "B: System" },
  { id: 216, question: "When is a census conducted in the United States?", choices: ["Every year", "Every 5 years", "Every 10 years", "Every 20 years"], correct: 2, explanation: "国勢調査は10年ごとに実施されます。下院議席の配分を決定するために使用されます。", isOfficial: false, is6520: false, category: "B: System" },
  { id: 217, question: "What determines House representation?", choices: ["Geography", "State populations", "State size", "Government choice"], correct: 1, explanation: "下院の代表者数は各州の人口によって決まります。", isOfficial: false, is6520: false, category: "B: System" },
  { id: 218, question: "What is a filibuster?", choices: ["A type of law", "Extended speech to delay votes", "A committee", "A voting method"], correct: 1, explanation: "フィリバスター（filibuster）は、上院の議員が演説を通じて投票を遅延させる戦術です。", isOfficial: false, is6520: false, category: "B: System" },
  { id: 219, question: "What is gerrymandering?", choices: ["A voting method", "Redrawing districts to gain advantage", "A type of election", "A Supreme Court case"], correct: 1, explanation: "ゲリマンダリングは、政党が選挙の利点を得るために選挙区を再編成することです。", isOfficial: false, is6520: false, category: "B: System" },
  { id: 220, question: "What does the First Amendment protect?", choices: ["Gun rights", "Freedom of speech", "Privacy rights", "Property rights"], correct: 1, explanation: "修正第1条は言論の自由、宗教の自由、報道の自由、集会の自由を保護します。", isOfficial: false, is6520: false, category: "C: Rights" },

  // More amendments and rights
  { id: 221, question: "What does the Second Amendment protect?", choices: ["Voting rights", "Right to bear arms", "Freedom of speech", "Jury trial"], correct: 1, explanation: "修正第2条は、規則的な民兵に必要である武器を保有して帯有する権利を保護します。", isOfficial: false, is6520: false, category: "C: Rights" },
  { id: 222, question: "What is the Fourth Amendment about?", choices: ["Right to vote", "Search and seizure", "Jury trial", "Double jeopardy"], correct: 1, explanation: "修正第4条は、不合理な捜索と押収から保護します。令状が必要です。", isOfficial: false, is6520: false, category: "C: Rights" },
  { id: 223, question: "What is the Fifth Amendment?", choices: ["Voting rights", "Self-incrimination protection", "Bear arms", "Jury rights"], correct: 1, explanation: "修正第5条は、自己負罪から保護し、適正法廷の権利を保障します。", isOfficial: false, is6520: false, category: "C: Rights" },
  { id: 224, question: "What is the Sixth Amendment about?", choices: ["Voting", "Right to fair trial", "Arms", "Searches"], correct: 1, explanation: "修正第6条は、迅速で公平な裁判、弁護士を持つ権利を保証します。", isOfficial: false, is6520: false, category: "C: Rights" },
  { id: 225, question: "What is the Seventh Amendment?", choices: ["Jury trial in civil cases", "Double jeopardy", "Jury trial in criminal cases", "Voting rights"], correct: 0, explanation: "修正第7条は、民事事件における陪審員裁判の権利を保証します。", isOfficial: false, is6520: false, category: "C: Rights" },
  { id: 226, question: "What is the Eighth Amendment?", choices: ["Cruel punishment", "Double jeopardy", "Self-incrimination", "Speedy trial"], correct: 0, explanation: "修正第8条は、残虐かつ異常な罰から保護します。", isOfficial: false, is6520: false, category: "C: Rights" },
  { id: 227, question: "What is the Ninth Amendment?", choices: ["Right to vote", "Unenumerated rights", "Privacy", "Travel"], correct: 1, explanation: "修正第9条は、憲法に列挙されていない権利も人民に属することを認めます。", isOfficial: false, is6520: false, category: "C: Rights" },
  { id: 228, question: "What is the 15th Amendment about?", choices: ["Women's voting", "Racial voting rights", "State rights", "Jury trials"], correct: 1, explanation: "修正第15条（1870年）は、人種による投票権の否定を禁止しています。", isOfficial: false, is6520: false, category: "C: Rights" },
  { id: 229, question: "What is the 19th Amendment?", choices: ["Women's voting rights", "Racial voting rights", "Male voting", "Age voting"], correct: 0, explanation: "修正第19条（1920年）は、すべての女性に投票権を与えました。", isOfficial: false, is6520: false, category: "C: Rights" },
  { id: 230, question: "What is the 26th Amendment?", choices: ["Voting age 21", "Voting age 18", "Voting age 25", "No age limit"], correct: 1, explanation: "修正第26条（1971年）は、投票年齢を18歳に設定しました。", isOfficial: false, is6520: false, category: "C: Rights" },
  { id: 231, question: "What is the Electoral College's role?", choices: ["Makes laws", "Elects president", "Confirms judges", "Writes budget"], correct: 1, explanation: "選挙人団は大統領選挙で州の投票を代表します。各州の選挙人数はその議会議員の総数です。", isOfficial: false, is6520: false, category: "B: System" },
  { id: 232, question: "How many electoral votes are needed to win the presidency?", choices: ["250", "270", "290", "300"], correct: 1, explanation: "大統領になるには、538の選挙人投票のうち270票が必要です。", isOfficial: false, is6520: false, category: "B: System" },
  { id: 233, question: "Can a president serve non-consecutive terms?", choices: ["Yes", "No", "Only once", "Depends on Congress"], correct: 1, explanation: "いいえ、修正第22条は大統領の任期を連続した2期に限定します。", isOfficial: false, is6520: false, category: "B: System" },
  { id: 234, question: "What is executive privilege?", choices: ["Presidential immunity", "Keeping information confidential", "Veto power", "Appointment power"], correct: 1, explanation: "行政特権は、大統領が特定の情報を秘密にできる権利です。国家安全保障のためです。", isOfficial: false, is6520: false, category: "B: System" },
  { id: 235, question: "What is the Treaty Power?", choices: ["Congress makes treaties", "President makes treaties with Senate approval", "President alone", "Supreme Court"], correct: 1, explanation: "大統領は条約を作成しますが、上院の2/3の承認が必要です。", isOfficial: false, is6520: false, category: "B: System" },
  { id: 236, question: "How many terms can a senator serve?", choices: ["Limited to 2", "Limited to 3", "Unlimited", "Limited to 1"], correct: 2, explanation: "上院議員の任期数に制限はありません。何度でも再選できます。", isOfficial: false, is6520: false, category: "B: System" },
  { id: 237, question: "How many terms can a House member serve?", choices: ["Limited to 4", "Limited to 6", "Unlimited", "Limited to 1"], correct: 2, explanation: "下院議員の任期数に制限はありません。何度でも再選できます。", isOfficial: false, is6520: false, category: "B: System" },
  { id: 238, question: "What is the 25th Amendment about?", choices: ["Presidential succession", "Voting rights", "Jury trials", "Search rights"], correct: 0, explanation: "修正第25条は、大統領が職務を遂行できない場合の継承を規定しています。", isOfficial: false, is6520: false, category: "B: System" },
  { id: 239, question: "Who has the power to declare war?", choices: ["President", "Congress", "Supreme Court", "Secretary of Defense"], correct: 1, explanation: "戦争宣言権は議会に属しています。憲法第1条に規定されています。", isOfficial: false, is6520: false, category: "B: System" },
  { id: 240, question: "What is the War Powers Act?", choices: ["Constitution clause", "1973 law limiting presidential war power", "Court ruling", "State law"], correct: 1, explanation: "戦争権限法（1973年）は、大統領が議会の承認なしに兵力を配置する期間を制限しています。", isOfficial: false, is6520: false, category: "B: System" },

  // Historical questions
  { id: 241, question: "What was Shays' Rebellion?", choices: ["Revolution", "Farmers' uprising for debt relief", "War with Britain", "Indian attack"], correct: 1, explanation: "シェイズ・レベリオン（1786年）は、マサチューセッツの農民が債務救済を求めて蜂起しました。", isOfficial: false, is6520: false, category: "D: Colonial" },
  { id: 242, question: "What was the significance of the Constitutional Convention?", choices: ["Declared independence", "Wrote the Constitution", "Started a war", "Abolished slavery"], correct: 1, explanation: "憲法制定会議（1787年）は、米国憲法を起草しました。", isOfficial: false, is6520: false, category: "D: Colonial" },
  { id: 243, question: "What were the Articles of Confederation?", choices: ["American treaties", "First U.S. government framework", "State documents", "British laws"], correct: 1, explanation: "連合規約は、独立戦争後の最初の米国政府の枠組みでした。弱すぎました。", isOfficial: false, is6520: false, category: "D: Colonial" },
  { id: 244, question: "Who was the first Chief Justice of the Supreme Court?", choices: ["John Jay", "John Marshall", "Thomas Jefferson", "George Washington"], correct: 0, explanation: "ジョン・ジェイが最初の最高裁判所長官でした（1789年-1795年）。", isOfficial: false, is6520: false, category: "D: Colonial" },
  { id: 245, question: "Who was the second President?", choices: ["Thomas Jefferson", "John Adams", "James Madison", "George Washington"], correct: 1, explanation: "ジョン・アダムスは第2代大統領（1797年-1801年）でした。", isOfficial: false, is6520: false, category: "D: Colonial" },
  { id: 246, question: "What was the XYZ Affair?", choices: ["French-American diplomatic incident", "Revolutionary battle", "Trade agreement", "Court case"], correct: 0, explanation: "XYZ事件は、フランスがアメリカ特使に賄賂を要求した1798年の外交事件です。", isOfficial: false, is6520: false, category: "D: Colonial" },
  { id: 247, question: "What was the Whiskey Rebellion?", choices: ["Protest against whiskey tax", "War with Britain", "Native American uprising", "Economic depression"], correct: 0, explanation: "ウイスキー反乱（1794年）はペンシルベニアの農民が連邦whiskey税に抗議しました。", isOfficial: false, is6520: false, category: "D: Colonial" },
  { id: 248, question: "What was the Missouri Compromise?", choices: ["Peace treaty", "Slavery expansion limits", "Economic agreement", "War settlement"], correct: 1, explanation: "ミズーリ妥協（1820年）は、奴隷州と自由州の数を均衡させるための協定です。", isOfficial: false, is6520: false, category: "E: 1800s" },
  { id: 249, question: "What was Manifest Destiny?", choices: ["A political party", "Belief in westward expansion", "A military strategy", "An economic policy"], correct: 1, explanation: "明白な運命は、アメリカが太平洋まで拡大すべき信念です。", isOfficial: false, is6520: false, category: "E: 1800s" },
  { id: 250, question: "What was the Indian Removal Act?", choices: ["Educational policy", "Military strategy", "Law forcing Native Americans westward", "Trade agreement"], correct: 2, explanation: "インディアン移住法（1830年）は、東の先住民族を西に強制移住させました。", isOfficial: false, is6520: false, category: "E: 1800s" },
  { id: 251, question: "What was the Trail of Tears?", choices: ["Native American migration", "Battle location", "Trade route", "Territory dispute"], correct: 0, explanation: "涙の道（1838年-1839年）は、チェロキー族が強制移住させられた死の行進です。", isOfficial: false, is6520: false, category: "E: 1800s" },
  { id: 252, question: "What caused the secession of Southern states?", choices: ["Trade disputes", "Lincoln's election", "Northern aggression", "Economic depression"], correct: 1, explanation: "南部の分離は、主にリンカーン大統領の選出によるもので、奴隷制が脅かされると懸念されました。", isOfficial: false, is6520: false, category: "E: 1800s" },
  { id: 253, question: "What was Reconstruction?", choices: ["Building houses", "Post-Civil War period", "Military strategy", "Political party"], correct: 1, explanation: "再建（1865年-1877年）は、南部を連邦に再統合し、改革する期間です。", isOfficial: false, is6520: false, category: "E: 1800s" },
  { id: 254, question: "What was the purpose of the Freedmen's Bureau?", choices: ["Organize labor", "Help freed slaves", "Control agriculture", "Collect taxes"], correct: 1, explanation: "解放奴隷庁（1865年-1872年）は、解放された奴隷に教育、医療、仕事支援を提供しました。", isOfficial: false, is6520: false, category: "E: 1800s" },
  { id: 255, question: "What was Plessy v. Ferguson?", choices: ["Voting rights case", "Separate but equal ruling", "Slavery case", "Property case"], correct: 1, explanation: "プレッシー対ファーガソン事件（1896年）は、分離だが平等を認めました。ブラウン対教育委員会で覆されました。", isOfficial: false, is6520: false, category: "F: Recent History" },
  { id: 256, question: "What was Brown v. Board of Education?", choices: ["Voting case", "School desegregation ruling", "Labor case", "Property dispute"], correct: 1, explanation: "ブラウン対教育委員会事件（1954年）は、学校の人種分離は違憲であると裁定しました。", isOfficial: false, is6520: false, category: "F: Recent History" },
  { id: 257, question: "What was the Great Society?", choices: ["Social club", "Johnson's reform programs", "War strategy", "Economic policy"], correct: 1, explanation: "グレート・ソサエティはリンドン・B・ジョンソン大統領の社会改革プログラムです。", isOfficial: false, is6520: false, category: "F: Recent History" },
  { id: 258, question: "What was the New Deal?", choices: ["Trade agreement", "Roosevelt's depression recovery programs", "Peace treaty", "Military strategy"], correct: 1, explanation: "ニューディール（1933年-1939年）はフランクリン・ルーズベルトの大恐慌対策プログラムです。", isOfficial: false, is6520: false, category: "F: Recent History" },
  { id: 259, question: "What was McCarthyism?", choices: ["Political party", "Anti-communist hysteria", "Court ruling", "Trade policy"], correct: 1, explanation: "マッカーシズムは1950年代の反共産主義ヒステリアで、冤罪告発につながりました。", isOfficial: false, is6520: false, category: "F: Recent History" },
  { id: 260, question: "What was Watergate?", choices: ["Bridge", "Presidential scandal", "War", "Political party"], correct: 1, explanation: "ウォーターゲートはリチャード・ニクソン大統領の1970年代のスキャンダルで、辞任につながりました。", isOfficial: false, is6520: false, category: "F: Recent History" },

  // Geography and symbols
  { id: 261, question: "What is the longest river in the United States?", choices: ["Colorado", "Mississippi", "Missouri", "Amazon"], correct: 1, explanation: "ミシシッピ川はアメリカで最長の川で、1738マイルです。", isOfficial: false, is6520: false, category: "G: Symbols" },
  { id: 262, question: "What is the highest mountain in the United States?", choices: ["Everest", "Denali", "Rocky Peak", "Yellowstone"], correct: 1, explanation: "デナリ（マッキンリー）はアラスカで、高さ20308フィートです。", isOfficial: false, is6520: false, category: "G: Symbols" },
  { id: 263, question: "What is the Great Plains?", choices: ["Mountain range", "Flat grassland region", "Ocean area", "Desert"], correct: 1, explanation: "グレート・プレーンズは中西部の広大な草地地域です。", isOfficial: false, is6520: false, category: "G: Symbols" },
  { id: 264, question: "What are the Great Lakes?", choices: ["Ocean waters", "Five largest freshwater lakes", "Salt water bodies", "Rivers"], correct: 1, explanation: "グレート・レイクスはミシガン、スペリオル、ミシガン、ウロン、エリー、オンタリオです。", isOfficial: false, is6520: false, category: "G: Symbols" },
  { id: 265, question: "What is Yellowstone?", choices: ["Mountain", "First national park", "City", "River"], correct: 1, explanation: "イエローストーンは1872年に設立された最初の国立公園です。", isOfficial: false, is6520: false, category: "G: Symbols" },
  { id: 266, question: "What is the Grand Canyon?", choices: ["Mountain range", "Famous geological formation", "River", "Desert"], correct: 1, explanation: "グランドキャニオンはアリゾナの有名な地質学的奇跡です。", isOfficial: false, is6520: false, category: "G: Symbols" },
  { id: 267, question: "What is the White House?", choices: ["Monument", "President's residence", "Government building", "Capitol"], correct: 1, explanation: "ホワイトハウスはアメリカ大統領の住所と執務室です。", isOfficial: false, is6520: false, category: "G: Symbols" },
  { id: 268, question: "What is the Capitol Building?", choices: ["Court building", "President's home", "Congress meeting place", "Museum"], correct: 2, explanation: "キャピトルビルはワシントン D.C. にあり、議会が会議を開きます。", isOfficial: false, is6520: false, category: "G: Symbols" },
  { id: 269, question: "What is Mount Rushmore?", choices: ["Mountain", "Presidential sculpture", "Monument", "All of the above"], correct: 3, explanation: "マウント・ラッシュモアはサウスダコタにある4人の大統領の彫像です。", isOfficial: false, is6520: false, category: "G: Symbols" },
  { id: 270, question: "What is the national bird?", choices: ["Owl", "Eagle", "Hawk", "Crow"], correct: 1, explanation: "鷲はアメリカの国鳥です。米国の強さと自由の象徴です。", isOfficial: false, is6520: false, category: "G: Symbols" },
  { id: 271, question: "What are the national colors?", choices: ["Blue and white", "Red, white, and blue", "Green and gold", "Black and white"], correct: 1, explanation: "赤、白、および青は米国の国家色です。", isOfficial: false, is6520: false, category: "G: Symbols" },
  { id: 272, question: "What is the Great Seal?", choices: ["Ocean creature", "National symbol", "Document", "Award"], correct: 1, explanation: "大紋章は米国の国家象徴で、ドルビルと公式文書に現れます。", isOfficial: false, is6520: false, category: "G: Symbols" },
  { id: 273, question: "What is the national motto?", choices: ["God Bless America", "In God We Trust", "United We Stand", "Land of the Free"], correct: 1, explanation: "『神を信じる』（In God We Trust）は米国の国のモットーです。", isOfficial: false, is6520: false, category: "G: Symbols" },
  { id: 274, question: "What year was the Constitution ratified?", choices: ["1776", "1787", "1789", "1791"], correct: 2, explanation: "米国憲法は1788年に批准され、1789年に効力を生じました。", isOfficial: false, is6520: false, category: "D: Colonial" },
  { id: 275, question: "How many original states were required to ratify the Constitution?", choices: ["7", "9", "11", "13"], correct: 1, explanation: "憲法が効力を持つには、13州のうち9州が批准する必要がありました。", isOfficial: false, is6520: false, category: "D: Colonial" },
  { id: 276, question: "What is the minimum age to be President?", choices: ["30", "35", "40", "25"], correct: 1, explanation: "大統領の最低年齢は35歳です。憲法第2条第1項で規定されています。", isOfficial: false, is6520: false, category: "B: System" },
  { id: 277, question: "What is the minimum age to be a Senator?", choices: ["25", "30", "35", "40"], correct: 0, explanation: "上院議員の最低年齢は30歳です。", isOfficial: false, is6520: false, category: "B: System" },
  { id: 278, question: "What is the minimum age to be a House member?", choices: ["21", "25", "30", "35"], correct: 0, explanation: "下院議員の最低年齢は25歳です。", isOfficial: false, is6520: false, category: "B: System" },
  { id: 279, question: "What is the minimum citizenship requirement for the President?", choices: ["5 years", "10 years", "14 years", "21 years"], correct: 2, explanation: "大統領は最低14年間の市民である必要があります。", isOfficial: false, is6520: false, category: "B: System" },
  { id: 280, question: "What is the minimum citizenship requirement for a Senator?", choices: ["5 years", "7 years", "9 years", "10 years"], correct: 3, explanation: "上院議員は最低9年間の米国市民である必要があります。", isOfficial: false, is6520: false, category: "B: System" },
];

